WITH by_dimension AS (SELECT d.category, COUNT(*) AS rows_total, ROUND(AVG(e.units), 2) AS avg_units, ROUND(AVG(e.revenue), 2) AS avg_revenue FROM store_sales e LEFT JOIN products d ON e.product_id = d.id GROUP BY CUBE (d.category)) SELECT category, rows_total, avg_units, avg_revenue, CASE WHEN category RLIKE '^(Books|Sports)$' THEN 'GROUP_B' ELSE 'GROUP_A' END AS category_zone FROM by_dimension ORDER BY avg_revenue;
